function userForm(email){const u=state.owners.find(u=>u.email===email)||{},orders=JSON.parse(u.assigned_orders||'[]');drawer('<h2>User access</h2><form id="userForm">'+field('name','Full Name','text',u.name||'',true)+field('email','Email','email',u.email||'',true)+field('department','Function / Department','text',u.department||'')+select('role','Security Role',['ADMIN','MARKETING','MP','PURCHASING','SOURCING','EUDR_REVIEWER','INTERNAL_USER','SUPPLIER_USER','VIEWER'],u.role||'INTERNAL_USER')+select('supplier_id','Supplier / Company',[['','Internal'],...state.suppliers.map(s=>[s.id,s.name])],u.supplier_id||'')+select('active','Active',['YES','NO'],u.active||'YES')+'<fieldset><legend>Assigned Orders</legend>'+state.cases.map(c=>`<label class="check"><input type="checkbox" name="order" value="${esc(c.id)}" ${orders.includes(c.id)?'checked':''}>${esc(c.so)}</label>`).join('')+'</fieldset><button>Save User</button></form>');$('userForm').elements.email.readOnly=!!u.email;$('userForm').onsubmit=async e=>{e.preventDefault();const form=new FormData(e.target),input=Object.fromEntries(form);input.assigned_orders=form.getAll('order');delete input.order;const saved=await act('manageUser',input);if(saved&&u.auth_uid&&input.active!==u.active){try{await authAction({action:'setEnabled',email:input.email,enabled:input.active==='YES'});}catch(error){$('msg').textContent=errorLabel(error);}}};}
async function provisionUser(email){if(!roles('ADMIN'))return;try{const result=await authAction({action:'provision',email});await load();drawer('<h2>Temporary password</h2><p>Copy this password now and deliver it through an approved secure channel. It will not be displayed again.</p><label>Username / Email<input readonly value="'+esc(result.email)+'"></label><label>Temporary password<input readonly type="text" value="'+esc(result.temporaryPassword)+'"></label><p>First login requires a password change.</p>');}catch(error){$('msg').textContent=errorLabel(error);}}
function suppliers(){$('main').innerHTML='<div class="pagehead"><h2>Suppliers</h2>'+button('Add Supplier','supplierForm')+'</div>'+state.suppliers.map(s=>`<div class="card"><h3>${esc(s.name)}</h3>${esc(s.email)} · ${s.active==='YES'?'Active':'Disabled'}<p>${button('Edit','supplierForm',s.id)}</p></div>`).join('');}

