function settings(){const keys=['RULES_CONFIRMED','LEGAL_RULE_VERSION','LEGAL_RULE_SOURCE_URL','ANNEX_I_VERSION','ANNEX_I_SOURCE_URL','COUNTRY_RISK_VERSION','COUNTRY_RISK_SOURCE_URL','LAST_LEGAL_REVIEW_DATE','LEGAL_REVIEWED_BY','LEGAL_REVIEW_MAX_DAYS'];$('main').innerHTML='<div class="card"><h2>Settings · Legal freshness</h2><p>Record the exact official versions checked and the responsible human reviewer. A version label alone does not validate evidence.</p><form id="settingsForm">'+keys.map(k=>k==='RULES_CONFIRMED'?select(k,k,['NO','YES'],state.settings.find(s=>s.key===k)?.value):field(k,k,k==='LAST_LEGAL_REVIEW_DATE'?'date':k.endsWith('_SOURCE_URL')?'url':'text',state.settings.find(s=>s.key===k)?.value||'')).join('')+'<button>Save Settings</button></form><h3>Production country risk</h3><p>Country risk applies to commodity production origin. Register only classifications checked against official EU sources.</p><form id="riskForm">'+field('country_code','ISO country code','text','',true)+select('risk_level','Risk',['LOW','STANDARD','HIGH'])+field('rule_version','Official version','text','',true)+field('checked_at','Checked date','date','',true)+field('source_url','Official EU source URL','url','',true)+'<button>Record Human Review</button></form></div>';$('settingsForm').onsubmit=e=>{e.preventDefault();act('saveSettings',Object.fromEntries(new FormData(e.target)));};$('riskForm').onsubmit=e=>{e.preventDefault();act('saveCountryRisk',Object.fromEntries(new FormData(e.target)));};}
