function exports(){
 $('main').innerHTML='<div class="card"><h2>Export Center</h2><p>Approved active originals and human-verified AI copies can be selected separately. ZIP files above 3 MB download in checked chunks without leaving this page.</p>'+select('exportOrder','Order',state.cases.map(c=>[c.id,c.so]),selected)+'<div id="exportList"></div></div>';
 const draw=()=>{const id=document.querySelector('[name="exportOrder"]').value;selected=id;const docs=state.docs.filter(d=>d.case_id===id),originals=docs.filter(d=>['SO','EVIDENCE'].includes(d.kind)),processed=docs.filter(d=>['REDACTED','EN_SUBTITLE'].includes(d.kind));
 const column=(title,items)=>`<fieldset class="export-column"><legend>${esc(title)}</legend>${items.length?items.map(d=>{const approved=d.status==='APPROVED'&&d.active_version==='YES',verified=!['REDACTED','EN_SUBTITLE'].includes(d.kind)||d.kind==='REDACTED'&&d.redaction_verified==='YES'||d.kind==='EN_SUBTITLE'&&d.translation_verified==='YES',available=approved&&verified;return `<label class="check"><input name="exportDoc" type="checkbox" value="${esc(d.id)}" ${available?'checked':'disabled'}><span>${esc(d.name)} · v${esc(d.version)} · ${esc(d.status)}${available?'':' · Not exportable yet'}</span></label>`;}).join(''):'<p class="muted">No documents in this group.</p>'}</fieldset>`;
 $('exportList').innerHTML='<div class="export-columns">'+column('Original approved documents',originals)+column('AI processed copies',processed)+'</div><div class="workspace-actions"><button id="exportFull">Full Package</button><button id="exportSelected">Selected Package</button></div>';
 const run=async full=>{const ids=[...document.querySelectorAll('[name="exportDoc"]:checked')].map(i=>i.value);if(!full&&!ids.length){$('msg').textContent=tt('Select at least one approved document.');return;}
 drawer('<h2>Export package</h2><p id="exportProgress" role="status">'+esc(tt('Exporting ZIP…'))+'</p><div id="exportResult"></div>');try{const result=await call('exportPackage',id,full?{}:{document_ids:ids});$('exportProgress').textContent=tt('ZIP is ready.');const target=$('exportResult');target.innerHTML='<p>'+esc(result.name)+' · '+Math.ceil((result.size_bytes||0)/1048576*10)/10+' MB</p><button id="downloadExport" type="button">'+esc(tt('Download ZIP'))+'</button><p class="muted">Download is available here, including packages above 3 MB within the current 25 MB transfer limit.</p>';$('downloadExport').onclick=()=>download(result.download_id);}
 catch(error){$('exportProgress').textContent=tt('Export failed.');$('exportResult').textContent=errorLabel(error);}};
 $('exportFull').onclick=()=>run(true);$('exportSelected').onclick=()=>run(false);i18n.translateUI($('exportList'));};document.querySelector('[name="exportOrder"]').onchange=draw;draw();}

function materialInfo(id){const m=state.materials.find(m=>m.id===id);if(!m)return;let countries=[];try{countries=JSON.parse(m.production_countries||'[]');}catch{}const risk=countries.map(code=>code+': '+(state.countryRisk.find(r=>r.country_code===code)?.risk_level||'NOT REVIEWED')).join('; ');drawer('<h2>Material Information · '+esc(m.material)+'</h2><p>Production country risk: '+esc(risk||'Production origin not provided')+'</p>'+ (cap('MATERIAL_EDIT')?'<form id="materialInfoForm">'+['commodity','common_species','scientific_name','hs_cn_code','quantity','quantity_uom','production_range'].map(k=>field(k,k.replace(/_/g,' '),'text',m[k]||'')).join('')+field('countries','Production countries (ISO codes, comma separated)','text',countries.join(','))+select('scope_status','Human scope assessment',['NOT_PROVIDED','REVIEW_REQUIRED','IN_SCOPE','OUT_OF_SCOPE'],m.scope_status||'NOT_PROVIDED')+field('scope_rule_version','Checked Annex I version','text',m.scope_rule_version||'')+select('metadata_source_document_id','Source for metadata',state.docs.filter(d=>d.case_id===m.case_id).map(d=>[d.id,d.name]),m.metadata_source_document_id||'')+field('metadata_reference','Source page and fields','text',m.metadata_reference||'',true)+field('legality','Legality evidence IDs (comma separated)','text',JSON.parse(m.legality_evidence_ids||'[]').join(','))+field('deforestation','Deforestation evidence IDs (comma separated)','text',JSON.parse(m.deforestation_evidence_ids||'[]').join(','))+'<button>Save source-backed information</button></form>':'<p>'+esc(m.scientific_name||'NOT PROVIDED')+'</p>'));if($('materialInfoForm'))$('materialInfoForm').onsubmit=e=>{e.preventDefault();const input=Object.fromEntries(new FormData(e.target)),list=s=>s.split(',').map(s=>s.trim()).filter(Boolean);input.production_countries=list(input.countries);input.legality_evidence_ids=list(input.legality);input.deforestation_evidence_ids=list(input.deforestation);delete input.countries;delete input.legality;delete input.deforestation;act('updateMaterialInfo',id,input);};}
