function bind(){document.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{const action=b.dataset.action,id=b.dataset.id;try{
 if(action==='open')go('Workspace',id);else if(action==='newOrder')newOrder();else if(action==='reopen'){drawer('<form id="reopenForm"><h2>Reopen workflow</h2><label>Reason<textarea name="comment" required></textarea></label><button>Confirm</button></form>');$('reopenForm').onsubmit=e=>{e.preventDefault();act('reopenCase',id,{confirmed:true,comment:new FormData(e.target).get('comment')});};}else if(action==='editOrder')editOrder(id);else if(action==='productEdit')productDialog(id);else if(action==='productImage')productImageUpload(id);else if(action==='removeProduct')await act('removeOrderProduct',id);else if(action==='materialEdit')materialEdit(id);else if(action==='aiOutputs')await aiOutputs(id);else if(action==='policy')policyDialog();else if(action==='taskRequirement')taskRequirementDialog(id);else if(action==='addRequirement')scopedRequirementDialog(id,b.dataset.block,selectedChainNode);else if(action==='repairSO')await act('repairExistingSOReviewTask',id);else if(action==='removeDraft')await act('removeDraftEvidence',id);else if(action==='chainEdit')chainEdit(id);else if(action==='grantCaps')grantCaps(id);else if(action==='openTasks')go('My Tasks');else if(action==='openOrders')go('Orders');else if(action==='document')await documentView(id);else if(action==='download')await download(id);else if(action==='registerExternal')externalOutputDialog(id);else if(action==='upload')upload(id);else if(action==='assign')assignDialog(id);else if(action==='materials')materialsDialog(id);else if(action==='addRelationship')chainDialog(id);else if(action==='geo')geoDialog(id);else if(action==='submit')await act('submitDocument',id);else if(action==='syncCalendar'){const r=await act('syncCalendar');$('msg').textContent=r?.some(x=>x.status==='CALENDAR_ACCESS_REQUIRED')?'Calendar access required; tasks remain saved.':r?.some(x=>x.status==='CALENDAR_SYNC_FAILED')?'Some Calendar events could not sync. Tasks remain saved.':'Calendar sync checked for your assigned tasks.';}
 else if(action.startsWith('prompt:'))await showPrompt(state.docs.find(d=>d.id===id).case_id,action.slice(7),id);else if(action.startsWith('processed:'))upload(id,action.slice(10));
 else if(action==='verifyProcessed'){const note=$('verificationNote').value.trim();if(!note)throw Error('Record verification checks in the review note first');await act('verifyProcessed',id,{verified:true,notes:note});}
 else if(action==='reviewGeo'){drawer('<h2>GEO review</h2><form id="geoReviewForm">'+select('status','Decision',['VERIFIED','REJECTED','MORE_INFO_REQUIRED'])+'<label>Review notes<textarea name="notes" required rows="4"></textarea></label><p>Verification does not certify deforestation-free status or legal compliance.</p><button>Record review</button></form>');$('geoReviewForm').onsubmit=e=>{e.preventDefault();act('reviewGeo',id,Object.fromEntries(new FormData(e.target)));};}
 else if(action==='closeOrder'||action==='finalReview')await finalDossier(id);else if(action==='materialInfo')materialInfo(id);else if(action==='certificate')certificateForm(id);else if(action==='readNotification')await act('markNotification',id);else if(action==='provision')await provisionUser(id);else if(action==='userForm')userForm(id);else if(action==='supplierForm')supplierForm(id);
 }catch(e){$('msg').textContent=errorLabel(e);}});}
