function editOrder(id){const c=state.cases.find(c=>c.id===id);drawer('<h2>Edit Order</h2><form id="editOrderForm">'+['so','customer','po','due'].map(k=>field(k,k,k==='due'?'date':'text',c[k]||'',k==='so')).join('')+'<p>Folder names are retained. Relationships use the immutable order ID.</p><button>Save</button></form>');$('editOrderForm').onsubmit=e=>{e.preventDefault();act('updateOrder',id,{...Object.fromEntries(new FormData(e.target)),expected_updated_at:c.updated_at});};}
